[package]
name = "probe"
version = "0.1.0"
edition = "2021"

[dependencies]
rustc-hash = "2"
fnv = "1"
EOF
cat > src/main.rs <<'EOF'
use rustc_hash::FxHashMap;
use std::collections::HashMap;
use std::hash::BuildHasherDefault;
use fnv::FnvHasher;

type FnvMap<K,V> = HashMap<K,V,BuildHasherDefault<FnvHasher>>;

fn simulate<M: std::ops::DerefMut<Target = HashMap<String,(f64,u64),S>> + std::ops::Deref<Target = HashMap<String,(f64,u64),S>>, S: std::hash::BuildHasher + Default>(_m: &mut M) {}

fn run_fx(existing: &[&str], imported: &[&str], remove_insert: bool) -> Vec<String> {
    let mut map: FxHashMap<String,(f64,u64)> = FxHashMap::default();
    for p in existing { map.insert(p.to_string(), (1.0, 100)); }
    for p in imported {
        if map.contains_key(*p) {
            if remove_insert {
                let mut v = map.remove(*p).unwrap();
                v.0 += 1.0;
                map.insert(p.to_string(), v);
            } else {
                map.get_mut(*p).unwrap().0 += 1.0;
            }
        } else {
            map.insert(p.to_string(), (1.0, 200));
        }
    }
    map.keys().cloned().collect()
}

fn main() {
    let cases: Vec<(&str, Vec<&str>, Vec<&str>, Vec<&str>)> = vec![
        ("A", vec!["zzz","aaa"], vec!["mmm"], vec!["aaa","mmm","zzz"]),
        ("C", vec!["zzz","aaa"], vec!["aaa","mmm"], vec!["aaa","zzz","mmm"]),
        ("L", vec!["zzz","aaa"], vec!["zzz","mmm"], vec!["aaa","mmm","zzz"]),
        ("K", vec!["zzz","aaa"], vec!["yyy","zzz","mmm"], vec!["aaa","mmm","yyy","zzz"]),
        ("E", vec!["zzz","bbb","aaa"], vec!["yyy","mmm"], vec!["aaa","bbb","mmm","yyy","zzz"]),
    ];
    for (name, existing, imported, expect) in &cases {
        for ri in [true, false] {
            let got = run_fx(existing, imported, ri);
            let mark = if &got == expect { "MATCH" } else { "----" };
            println!("fx ri={} case {}: got {:?} expect {:?} {}", ri, name, got, expect, mark);
        }
    }
}
EOF
cargo run -q 2>&1 | tail -20

