const SEED: u64 = 0x51_7c_c1_b7_27_22_0a_95;
impl FxHasher {
    #[inline] fn add_to_hash(&mut self, i: u64) {
        self.hash = (self.hash.rotate_left(5) ^ i).wrapping_mul(SEED);
    }
}
impl Hasher for FxHasher {
    #[inline] fn write(&mut self, bytes: &[u8]) {
        // rustc-hash 1.x: processes usize chunks; for str, hash writes bytes then write_u8(0xff)? 
        // Hash for str calls write(bytes) then write_u8(0xff)
        let mut b = bytes;
        while b.len() >= 8 {
            let mut buf = [0u8;8]; buf.copy_from_slice(&b[..8]);
